var lengthOfLastWord = function(s) {
    let i = s.length - 1;

    // Skip any trailing spaces
    while (i >= 0 && s[i] === ' ') {
        i = i - 1;
    }

    // Count characters of the last word
    let length = 0;
    while (i >= 0 && s[i] !== ' ') {
        length = length + 1;
        i = i - 1;
    }

    return length;
};
